    let mut launch = ResolvedLaunch::resolve(
        image,
        command.to_vec(),
        env.to_vec(),
        workdir.map(str::to_string),
        user.map(str::to_string),
    )?;

    let (cid, rootfs) = match resolve_main_container(Some(overlay_id)) {
        Some(c) => (c, storage::persistent_overlay_rootfs(overlay_id)),
